import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_ACTIVIDAD, MODELO_CLUB } from '../../models/club-actividad.model.mjs';

export async function trasladarActividadRepository(actividadId, clubId) {
  const { Attributes } = await MODELO_ACTIVIDAD.build(EntityRepository).update(
    { actividadId, clubId },
    {
      condition: { attr: 'actividadId', exists: true },
      returnValues: 'ALL_NEW'
    }
  );
  return Attributes;
}

import { consultarClubService } from './service.mjs';

export async function handler(event) {
  const clubId = Number(event.pathParameters.clubId);
  const minimo = Number(event.queryStringParameters?.minimo ?? 0);
  const resultado = await consultarClubService(clubId, minimo);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { buscarClubRepository, consultarClubRepository } from './repository.mjs';

export async function consultarClubService(clubId, minimo) {
  const club = await buscarClubRepository(clubId);
  if (!club) throw new Error('Club no encontrado');
  const actividades = await consultarClubRepository(clubId, minimo);
  return { club, actividades };
}

import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_ACTIVIDAD, MODELO_CLUB } from '../../models/club-actividad.model.mjs';

export async function buscarClubRepository(clubId) {
  const { Item } = await MODELO_CLUB.build(EntityRepository).get(
    { clubId },
    { consistent: true }
  );
  return Item ?? null;
}

export async function consultarClubRepository(clubId, minimo) {
  const { Items = [] } = await MODELO_ACTIVIDAD.build(EntityRepository).query(
    { index: 'PorClub', partition: clubId },
    { filters: { Actividad: { attr: 'plazas', gte: minimo } } }
  );
  return Items;
}
